1	/** Flat fee added to every premium, regardless of the items insured. */
2	const PROCESSING_FEE = 5;
3	
4	/** Base premium of each insurable item type. */
5	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
6	  sword: 100,
7	  amulet: 60,
8	  staff: 80,
9	  potion: 40,
10	  rune: 25,
11	  moonstone: 25,
12	};
13	
14	/** Initial assessment surcharge on a customer's first insurance. */
15	const FIRST_INSURANCE_RATE = 0.1;
16	
17	export type Scenario = {
18	  customer: { yearsWithMHPCO: number };
19	  steps: Step[];
20	};
21	
22	export type Step = {
23	  op: string;
24	  items: Item[];
25	};
26	
27	export type Item = { type: string } & Record<string, unknown>;
28	
29	export type Result = { premium: number };
30	
31	export type ScenarioOutcome = { results: Result[] };
32	
33	/** A block is exactly this many items of one and the same type. */
34	const BLOCK_SIZE = 3;
35	
36	/** Special base premium charged for a complete block, instead of the per-item sum. */
37	const BLOCK_BASE_PREMIUM = 60;
38	
39	/** Number of items of each type on a policy. */
40	const countByType = (items: Item[]): Map<string, number> => {
41	  const counts = new Map<string, number>();
42	  for (const item of items) {
43	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
44	  }
45	  return counts;
46	};
47	
48	/** Base premium of a single item, before any block pricing or surcharge. */
49	const itemBasePremium = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
50	
51	/** Base premium for all items of one and the same type. */
52	const groupBasePremium = (type: string, count: number): number =>
53	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUM_BY_TYPE[type];
54	
55	/** Base premium of a policy covering the given items. */
56	const calculateBasePremium = (items: Item[]): number =>
57	  [...countByType(items)].reduce(
58	    (total, [type, count]) => total + groupBasePremium(type, count),
59	    0,
60	  );
61	
62	/** Risk surcharge charged on the base premium of a cursed item. */
63	const CURSE_RATE = 0.5;
64	
65	/** Enchantment level from which an item counts as highly enchanted. */
66	const HIGH_ENCHANTMENT_LEVEL = 5;
67	
68	/** Risk surcharge charged on the base premium of a highly enchanted item. */
69	const HIGH_ENCHANTMENT_RATE = 0.3;
70	
71	/** True when the item is enchanted strongly enough to attract the surcharge. */
72	const isHighlyEnchanted = (item: Item): boolean =>
73	  typeof item.enchantment === "number" &&
74	  item.enchantment >= HIGH_ENCHANTMENT_LEVEL;
75	
76	/** Surcharges an individual item attracts, charged on its own base premium. */
77	const itemSurcharge = (item: Item): number => {
78	  const curse = item.cursed ? CURSE_RATE : 0;
79	  const enchantment = isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_RATE : 0;
80	  return itemBasePremium(item) * (curse + enchantment);
81	};
82	
83	/** Surcharges that attach to individual items rather than to the whole policy. */
84	const calculateItemSurcharges = (items: Item[]): number =>
85	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
86	
87	/** Surcharges that attach to the policy as a whole, charged on its base premium. */
88	const calculatePolicySurcharges = (policyBasePremium: number): number =>
89	  policyBasePremium * FIRST_INSURANCE_RATE;
90	
91	/** Premiums are rounded up — fractions of a gold piece fall to MHPCO. */
92	const roundPremiumUp = (amount: number): number => Math.ceil(amount);
93	
94	/** Price a policy covering the given items. */
95	const quotePremium = (items: Item[]): number => {
96	  const policyBasePremium = calculateBasePremium(items);
97	  const itemSurcharges = calculateItemSurcharges(items);
98	  const policySurcharges = calculatePolicySurcharges(policyBasePremium);
99	  return roundPremiumUp(
100	    policyBasePremium + itemSurcharges + policySurcharges + PROCESSING_FEE,
101	  );
102	};
103	
104	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
105	  results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })),
106	});
